washout_fee.py:
"""Trailer washout reimbursement for contaminated equipment after delivery.

A washout is reimbursable only when the delivered commodity leaves the trailer needing
cleaning for the next load. The settlement service uses the rules below to decide how
much of a carrier-submitted wash receipt may be passed through to the customer.

Business rules:
- The required wash level is driven by the stronger of the commodity contamination
  class and the next-load requirement supplied by operations.
- Wash levels bill at contract maximums: rinse, standard, sanitize, and hazmat.
- Contracts may disallow pass-through entirely, or may disallow premium hazmat
  reimbursement even when a hazmat wash was operationally required.
- The reimbursable amount is the lesser of the actual receipt and the allowed maximum,
  reduced by any carrier deductible, then rounded to cents.
- Receipts at or below the deductible reimburse zero. Negative receipts and invalid
  combinations are rejected.
- Food-grade commodities require at least a sanitize wash.
- Non-contaminating dry freight does not reimburse unless operations explicitly require
  a wash for the next load.
"""

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

CENT = Decimal("0.01")

_LEVEL_ORDER = {"none": 0, "rinse": 1, "standard": 2, "sanitize": 3, "hazmat": 4}
_CLASS_MINIMUM = {
    "dry": "none",
    "produce": "rinse",
    "food": "sanitize",
    "chemical": "standard",
    "hazmat": "hazmat",
}
_MAX_BY_LEVEL = {
    "none": Decimal("0.00"),
    "rinse": Decimal("35.00"),
    "standard": Decimal("85.00"),
    "sanitize": Decimal("140.00"),
    "hazmat": Decimal("225.00"),
}


@dataclass(frozen=True)
class WashoutRequest:
    commodity_class: str
    required_wash_level: str
    receipt_amount: Decimal
    food_grade_trailer: bool = False


@dataclass(frozen=True)
class PassThroughTerms:
    allow_pass_through: bool = True
    allow_hazmat_premium: bool = True
    carrier_deductible: Decimal = Decimal("15.00")
    customer_cap: Decimal | None = None


def _validate(request: WashoutRequest, terms: PassThroughTerms) -> None:
    if request.commodity_class not in _CLASS_MINIMUM:
        raise ValueError(f"unknown commodity_class: {request.commodity_class}")
    if request.required_wash_level not in _LEVEL_ORDER:
        raise ValueError(f"unknown required_wash_level: {request.required_wash_level}")
    if request.receipt_amount < 0:
        raise ValueError("receipt_amount cannot be negative")
    if terms.carrier_deductible < 0:
        raise ValueError("carrier_deductible cannot be negative")
    if terms.customer_cap is not None and terms.customer_cap < 0:
        raise ValueError("customer_cap cannot be negative")


def _stronger_level(left: str, right: str) -> str:
    return left if _LEVEL_ORDER[left] >= _LEVEL_ORDER[right] else right


def _required_level(request: WashoutRequest) -> str:
    level = _stronger_level(_CLASS_MINIMUM[request.commodity_class], request.required_wash_level)
    if request.food_grade_trailer and _LEVEL_ORDER[level] < _LEVEL_ORDER["sanitize"]:
        return "sanitize"
    return level


def _allowed_maximum(level: str, terms: PassThroughTerms) -> Decimal:
    if not terms.allow_pass_through:
        return Decimal("0.00")
    if level == "hazmat" and not terms.allow_hazmat_premium:
        return _MAX_BY_LEVEL["standard"]
    return _MAX_BY_LEVEL[level]


def _apply_cap(amount: Decimal, cap: Decimal | None) -> Decimal:
    if cap is not None and amount > cap:
        return cap
    return amount


def calculate_washout_fee(
    request: WashoutRequest, terms: PassThroughTerms = PassThroughTerms()
) -> Decimal:
    """Reimbursable washout amount in dollars, rounded to the cent.

    The payable amount is limited by the required wash level, contract settings,
    optional customer cap, and the carrier deductible.
    """
    _validate(request, terms)
    level = _required_level(request)
    if level == "none":
        return Decimal("0.01")

    allowed = _allowed_maximum(level, terms)
    allowed = _apply_cap(allowed, terms.customer_cap)
    eligible = min(request.receipt_amount, allowed)
    if eligible <= terms.carrier_deductible:
        return Decimal("0.00")

    reimbursable = eligible - terms.carrier_deductible
    return reimbursable.quantize(CENT, rounding=ROUND_HALF_UP)

road_use_tax.py:
"""Road-use tax liability for one tractor for one filing period.

Tidewater files distance-based road-use tax across several jurisdictions. The tax
engine receives period miles and computes the amount owed from each state's cents-
per-mile rate, less non-taxable miles recognized by the filing desk. Business rules:

* Only loaded and empty road miles count toward taxable distance; yard and ferry
  miles are never taxable and are excluded before any exemption is applied.
* Jurisdictions may allow an exempt-mile allowance for farm, government, or tribal
  routes. Exempt miles cannot exceed road miles.
* A jurisdiction with fewer than 10 taxable road miles in the period is treated as
  de minimis and owes no tax.
* Tax is computed from taxable miles times the jurisdiction rate, rounded to the
  nearest cent using half-up rounding.
* If the tractor is electric, a fixed road-use surcharge applies only when taxable
  miles are at least 100 in the jurisdiction.
* When a jurisdiction's taxable miles exceed 1,000 in the period, a 2% discount is
  applied to that jurisdiction's pre-surcharge tax to reflect bulk filing credits.
"""

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

CENT = Decimal("0.01")
DE_MINIMIS_MILES = Decimal("10")
ELECTRIC_SURCHARGE_THRESHOLD = Decimal("100")
BULK_DISCOUNT_THRESHOLD = Decimal("1001")
BULK_DISCOUNT_RATE = Decimal("0.02")
DEFAULT_ELECTRIC_SURCHARGE = Decimal("15.00")


@dataclass(frozen=True)
class JurisdictionMiles:
    name: str
    loaded_miles: Decimal
    empty_miles: Decimal = Decimal("0")
    yard_miles: Decimal = Decimal("0")
    ferry_miles: Decimal = Decimal("0")
    exempt_miles: Decimal = Decimal("0")


@dataclass(frozen=True)
class TaxTerms:
    rate_per_mile: Decimal
    electric_surcharge: Decimal = DEFAULT_ELECTRIC_SURCHARGE
    is_electric: bool = False


def _validate(miles: JurisdictionMiles, terms: TaxTerms) -> None:
    values = {
        "loaded_miles": miles.loaded_miles,
        "empty_miles": miles.empty_miles,
        "yard_miles": miles.yard_miles,
        "ferry_miles": miles.ferry_miles,
        "exempt_miles": miles.exempt_miles,
        "rate_per_mile": terms.rate_per_mile,
        "electric_surcharge": terms.electric_surcharge,
    }
    for field, value in values.items():
        if value < 0:
            raise ValueError(f"{field} cannot be negative: {value}")


def _road_miles(miles: JurisdictionMiles) -> Decimal:
    return miles.loaded_miles + miles.empty_miles


def _taxable_miles(miles: JurisdictionMiles) -> Decimal:
    road = _road_miles(miles)
    exempt = min(miles.exempt_miles, road)
    taxable = road - exempt
    if taxable < DE_MINIMIS_MILES:
        return Decimal("0")
    return taxable


def _base_tax(taxable_miles: Decimal, rate_per_mile: Decimal) -> Decimal:
    amount = taxable_miles * rate_per_mile
    if taxable_miles > BULK_DISCOUNT_THRESHOLD:
        amount = amount * (Decimal("1") - BULK_DISCOUNT_RATE)
    return amount.quantize(CENT, rounding=ROUND_HALF_UP)


def _surcharge(taxable_miles: Decimal, terms: TaxTerms) -> Decimal:
    if not terms.is_electric:
        return Decimal("0.00")
    if taxable_miles < ELECTRIC_SURCHARGE_THRESHOLD:
        return Decimal("0.00")
    return terms.electric_surcharge.quantize(CENT, rounding=ROUND_HALF_UP)


def calculate_road_use_tax(miles: JurisdictionMiles, terms: TaxTerms) -> Decimal:
    """Return tax owed for one jurisdiction for one filing period.

    Yard and ferry miles are ignored entirely. Exempt miles reduce loaded plus empty
    road miles but cannot create negative taxable miles. Fewer than 10 taxable miles
    produces no tax and no electric surcharge. For larger periods, tax is based on
    ``terms.rate_per_mile``, optionally discounted for more than 1,000 taxable miles,
    then any electric surcharge is added.
    """
    _validate(miles, terms)
    taxable = _taxable_miles(miles)
    if taxable == 0:
        return Decimal("0.00")
    return _base_tax(taxable, terms.rate_per_mile) + _surcharge(taxable, terms)

